# Generated from tools/data/rulebooks/backgammon.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  class Backgammon
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:play, GameRoomRules.translate("Moving and bearing off"),
            GameRoomRules.translate("Two people play. Move all your checkers towards your home, points 1 to 6, then bear them off before your opponent. Each player numbers the board in their own direction: your point 24 is your opponent\u2019s point 1. The opening roll gives each player one die. Reroll a tie; the higher die starts and uses both values. After that, roll two dice each turn. Doubles give four moves of the same value."),
            GameRoomRules.translate("Each die is a separate move. You may move two checkers or one checker twice, but its intermediate point must also be available. Use as many dice as legally possible. If only one of two different dice can be used and either value allows a move, use the higher one. Two or more opposing checkers block a point. Landing on one opposing checker hits it onto the bar. Checkers on the bar must re-enter before any other checker moves; a 3 enters on your point 22."),
            GameRoomRules.translate("When every checker still on the board is in your home, you may bear off. A 4 removes a checker from point 4. If there are no checkers on point 4 or any higher point, that die may remove a checker from the highest occupied point below 4. If no legal move remains, the turn passes automatically.")),
          rule_section(:variants, GameRoomRules.translate("Variants"),
            GameRoomRules.translate("Classic starts with fifteen checkers: two on point 24, five on 13, three on 8 and five on 6. Nackgammon starts with two each on 24 and 23, four each on 13 and 6, and three on 8. Hypergammon has only three checkers, one each on 24, 23 and 22. LongGammon starts all fifteen on point 24. The Egyptian rule uses the classic setup but allows at most five of your checkers on a board point; the bar and borne-off checkers are not limited.")),
          rule_section(:match, GameRoomRules.translate("Match score and doubling"),
            GameRoomRules.translate("A win is worth one point if the opponent has borne off any checker, two if none have been borne off, or three if none have been borne off and an opposing checker is still on the bar or in your home. At table creation, a score limit of zero means one game. A positive limit starts further games until someone reaches it."),
            GameRoomRules.translate("If the doubling cube is enabled, before rolling you may select Offer a double and press Enter. Your opponent accepts or concedes this game at the old stake. Accepting doubles the stake and gives that player the right to offer the next double, up to 64. The normal one-, two- or three-point win is multiplied by the stake. The first time someone is one point short of the match target, doubling is disabled for the next game only: the Crawford game.")),
          rule_section(:controls, GameRoomRules.translate("Keyboard"),
            GameRoomRules.translate("Enter: roll, confirm a cube decision, or select a checker and then its destination."),
            GameRoomRules.translate("Arrows: move around the board or choose a decision. The upper row runs from 24 to 13, the lower from 1 to 12, both left to right. The bar is left of 24; borne-off checkers are left of 1. With a checker on the bar, you can select its entry point directly."),
            GameRoomRules.translate("Escape: cancel selection of a checker."),
            GameRoomRules.translate("V: inspect the board without moving checkers."),
            GameRoomRules.translate("D: read the dice still available this turn."),
            GameRoomRules.translate("Space: read the remaining dice while moving."),
            GameRoomRules.translate("B: read checkers on the bar for both players."),
            GameRoomRules.translate("Z: read borne-off checkers for both players."),
            GameRoomRules.translate("S: read the match score."))
        ]
      end

      def localized_rule_sections
