          [
            rule_section(:play, "\u0425\u043E\u0434\u044B \u0438 \u0441\u043D\u044F\u0442\u0438\u0435 \u0448\u0430\u0448\u0435\u043A",
              "\u0418\u0433\u0440\u0430\u044E\u0442 \u0434\u0432\u043E\u0435. \u041F\u0435\u0440\u0435\u0432\u0435\u0434\u0438\u0442\u0435 \u0432\u0441\u0435 \u0448\u0430\u0448\u043A\u0438 \u0432 \u0441\u0432\u043E\u0439 \u0434\u043E\u043C, \u043D\u0430 \u043F\u0443\u043D\u043A\u0442\u044B \u043E\u0442 1 \u0434\u043E 6, \u0438 \u0441\u043D\u0438\u043C\u0438\u0442\u0435 \u0438\u0445 \u0440\u0430\u043D\u044C\u0448\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430. \u041A\u0430\u0436\u0434\u044B\u0439 \u043D\u0443\u043C\u0435\u0440\u0443\u0435\u0442 \u0434\u043E\u0441\u043A\u0443 \u0441\u043E \u0441\u0432\u043E\u0435\u0439 \u0441\u0442\u043E\u0440\u043E\u043D\u044B: \u0432\u0430\u0448 \u043F\u0443\u043D\u043A\u0442 24 \u2014 \u044D\u0442\u043E \u043F\u0443\u043D\u043A\u0442 1 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430. \u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u043C\u0443 \u0431\u0440\u043E\u0441\u0430\u0435\u0442\u0441\u044F \u043F\u043E \u043E\u0434\u043D\u043E\u043C\u0443 \u043A\u0443\u0431\u0438\u043A\u0443. \u041F\u0440\u0438 \u0440\u0430\u0432\u0435\u043D\u0441\u0442\u0432\u0435 \u0431\u0440\u043E\u0441\u043E\u043A \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442\u0441\u044F; \u0441\u0442\u0430\u0440\u0448\u0435\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u043E\u0431\u0430 \u043A\u0443\u0431\u0438\u043A\u0430. \u0417\u0430\u0442\u0435\u043C \u0432 \u043A\u0430\u0436\u0434\u044B\u0439 \u0445\u043E\u0434 \u0431\u0440\u043E\u0441\u0430\u044E\u0442\u0441\u044F \u0434\u0432\u0430 \u043A\u0443\u0431\u0438\u043A\u0430. \u0414\u0443\u0431\u043B\u044C \u0434\u0430\u0451\u0442 \u0447\u0435\u0442\u044B\u0440\u0435 \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0435\u043D\u0438\u044F \u043D\u0430 \u0432\u044B\u043F\u0430\u0432\u0448\u0435\u0435 \u0447\u0438\u0441\u043B\u043E.",
              "\u041A\u0430\u0436\u0434\u044B\u0439 \u043A\u0443\u0431\u0438\u043A \u0437\u0430\u0434\u0430\u0451\u0442 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0435 \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0435\u043D\u0438\u0435. \u041C\u043E\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u0434\u0432\u0438\u043D\u0443\u0442\u044C \u0434\u0432\u0435 \u0448\u0430\u0448\u043A\u0438 \u0438\u043B\u0438 \u043E\u0434\u043D\u0443 \u0434\u0432\u0430\u0436\u0434\u044B, \u043D\u043E \u043F\u0440\u043E\u043C\u0435\u0436\u0443\u0442\u043E\u0447\u043D\u044B\u0439 \u043F\u0443\u043D\u043A\u0442 \u0442\u043E\u0436\u0435 \u0434\u043E\u043B\u0436\u0435\u043D \u0431\u044B\u0442\u044C \u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D. \u041D\u0443\u0436\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u043A\u0430\u043A \u043C\u043E\u0436\u043D\u043E \u0431\u043E\u043B\u044C\u0448\u0435 \u043A\u0443\u0431\u0438\u043A\u043E\u0432. \u0415\u0441\u043B\u0438 \u0438\u0437 \u0434\u0432\u0443\u0445 \u0440\u0430\u0437\u043D\u044B\u0445 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0439 \u043C\u043E\u0436\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u043D\u043E \u0438 \u0445\u043E\u0434 \u0432\u043E\u0437\u043C\u043E\u0436\u0435\u043D \u0441 \u043B\u044E\u0431\u044B\u043C, \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435 \u0441\u0442\u0430\u0440\u0448\u0435\u0435. \u0414\u0432\u0435 \u0438 \u0431\u043E\u043B\u0435\u0435 \u0448\u0430\u0448\u043A\u0438 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u044E\u0442 \u043F\u0443\u043D\u043A\u0442. \u041E\u0434\u0438\u043D\u043E\u0447\u043D\u0430\u044F \u0448\u0430\u0448\u043A\u0430 \u043F\u0440\u0438 \u043F\u043E\u043F\u0430\u0434\u0430\u043D\u0438\u0438 \u043D\u0430 \u043D\u0435\u0451 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043D\u0430 \u0431\u0430\u0440. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043D\u0443\u0436\u043D\u043E \u0432\u0432\u0435\u0441\u0442\u0438 \u0448\u0430\u0448\u043A\u0438 \u0441 \u0431\u0430\u0440\u0430; \u0442\u0440\u043E\u0439\u043A\u0430 \u0432\u0432\u043E\u0434\u0438\u0442 \u043D\u0430 \u0432\u0430\u0448 \u043F\u0443\u043D\u043A\u0442 22.",
              "\u041A\u043E\u0433\u0434\u0430 \u0432\u0441\u0435 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u043D\u0430 \u0434\u043E\u0441\u043A\u0435 \u0448\u0430\u0448\u043A\u0438 \u043D\u0430\u0445\u043E\u0434\u044F\u0442\u0441\u044F \u0432 \u0432\u0430\u0448\u0435\u043C \u0434\u043E\u043C\u0435, \u0438\u0445 \u043C\u043E\u0436\u043D\u043E \u0441\u043D\u0438\u043C\u0430\u0442\u044C. \u0427\u0435\u0442\u0432\u0451\u0440\u043A\u0430 \u0441\u043D\u0438\u043C\u0430\u0435\u0442 \u0448\u0430\u0448\u043A\u0443 \u0441 \u043F\u0443\u043D\u043A\u0442\u0430 4. \u0415\u0441\u043B\u0438 \u043D\u0430 \u043F\u0443\u043D\u043A\u0442\u0435 4 \u0438 \u0432\u044B\u0448\u0435 \u0448\u0430\u0448\u0435\u043A \u043D\u0435\u0442, \u0435\u044E \u043C\u043E\u0436\u043D\u043E \u0441\u043D\u044F\u0442\u044C \u0448\u0430\u0448\u043A\u0443 \u0441 \u0441\u0430\u043C\u043E\u0433\u043E \u0441\u0442\u0430\u0440\u0448\u0435\u0433\u043E \u0437\u0430\u043D\u044F\u0442\u043E\u0433\u043E \u043F\u0443\u043D\u043A\u0442\u0430 \u043D\u0438\u0436\u0435 4. \u0415\u0441\u043B\u0438 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u044B\u0445 \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0435\u043D\u0438\u0439 \u043D\u0435\u0442, \u0445\u043E\u0434 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0443."),
            rule_section(:variants, "\u0412\u0430\u0440\u0438\u0430\u043D\u0442\u044B",
              "\u0412 \u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u043E\u043C \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 \u043F\u044F\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0448\u0430\u0448\u0435\u043A: \u0434\u0432\u0435 \u043D\u0430 \u043F\u0443\u043D\u043A\u0442\u0435 24, \u043F\u044F\u0442\u044C \u043D\u0430 13, \u0442\u0440\u0438 \u043D\u0430 8 \u0438 \u043F\u044F\u0442\u044C \u043D\u0430 6. \u0412 Nackgammon \u043F\u043E \u0434\u0432\u0435 \u043D\u0430 24 \u0438 23, \u043F\u043E \u0447\u0435\u0442\u044B\u0440\u0435 \u043D\u0430 13 \u0438 6 \u0438 \u0442\u0440\u0438 \u043D\u0430 8. \u0412 Hypergammon \u0442\u043E\u043B\u044C\u043A\u043E \u0442\u0440\u0438 \u0448\u0430\u0448\u043A\u0438: \u043F\u043E \u043E\u0434\u043D\u043E\u0439 \u043D\u0430 24, 23 \u0438 22. \u0412 LongGammon \u0432\u0441\u0435 \u043F\u044F\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0442 \u043D\u0430 \u043F\u0443\u043D\u043A\u0442\u0435 24. \u0415\u0433\u0438\u043F\u0435\u0442\u0441\u043A\u043E\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0443\u044E \u0440\u0430\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0443, \u043D\u043E \u043D\u0430 \u043E\u0434\u043D\u043E\u043C \u043F\u0443\u043D\u043A\u0442\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u043D\u0435 \u0431\u043E\u043B\u0435\u0435 \u043F\u044F\u0442\u0438 \u0432\u0430\u0448\u0438\u0445 \u0448\u0430\u0448\u0435\u043A; \u0431\u0430\u0440 \u0438 \u0441\u043D\u044F\u0442\u044B\u0435 \u0448\u0430\u0448\u043A\u0438 \u043D\u0435 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u044B."),
            rule_section(:match, "\u0421\u0447\u0451\u0442 \u043C\u0430\u0442\u0447\u0430 \u0438 \u0443\u0434\u0432\u043E\u0435\u043D\u0438\u0435",
              "\u041F\u043E\u0431\u0435\u0434\u0430 \u0434\u0430\u0451\u0442 \u043E\u0434\u043D\u043E \u043E\u0447\u043A\u043E, \u0435\u0441\u043B\u0438 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u0441\u043D\u044F\u043B \u0445\u043E\u0442\u044F \u0431\u044B \u043E\u0434\u043D\u0443 \u0448\u0430\u0448\u043A\u0443, \u0434\u0432\u0430 \u2014 \u0435\u0441\u043B\u0438 \u043D\u0435 \u0441\u043D\u044F\u043B \u043D\u0438 \u043E\u0434\u043D\u043E\u0439, \u0438\u043B\u0438 \u0442\u0440\u0438 \u2014 \u0435\u0441\u043B\u0438 \u043F\u0440\u0438 \u044D\u0442\u043E\u043C \u0435\u0433\u043E \u0448\u0430\u0448\u043A\u0430 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043D\u0430 \u0431\u0430\u0440\u0435 \u043B\u0438\u0431\u043E \u0432 \u0432\u0430\u0448\u0435\u043C \u0434\u043E\u043C\u0435. \u041F\u0440\u0438 \u0441\u043E\u0437\u0434\u0430\u043D\u0438\u0438 \u0441\u0442\u043E\u043B\u0430 \u043D\u0443\u043B\u0435\u0432\u043E\u0439 \u043F\u0440\u0435\u0434\u0435\u043B \u043E\u0447\u043A\u043E\u0432 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043E\u0434\u043D\u0443 \u043F\u0430\u0440\u0442\u0438\u044E. \u041F\u0440\u0438 \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u043C \u043F\u0440\u0435\u0434\u0435\u043B\u0435 \u043F\u0430\u0440\u0442\u0438\u0438 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u044E\u0442\u0441\u044F, \u043F\u043E\u043A\u0430 \u043A\u0442\u043E-\u0442\u043E \u0435\u0433\u043E \u043D\u0435 \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0435\u0442.",
              "\u0415\u0441\u043B\u0438 \u0432\u043A\u043B\u044E\u0447\u0451\u043D \u043A\u0443\u0431 \u0443\u0434\u0432\u043E\u0435\u043D\u0438\u044F, \u043F\u0435\u0440\u0435\u0434 \u0431\u0440\u043E\u0441\u043A\u043E\u043C \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0443\u0434\u0432\u043E\u0438\u0442\u044C \u0438 \u043D\u0430\u0436\u0430\u0442\u044C Enter. \u0421\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442 \u0438\u043B\u0438 \u0441\u0434\u0430\u0451\u0442 \u044D\u0442\u0443 \u043F\u0430\u0440\u0442\u0438\u044E \u043F\u043E \u043F\u0440\u0435\u0436\u043D\u0435\u0439 \u0441\u0442\u0430\u0432\u043A\u0435. \u041F\u0440\u0438\u043D\u044F\u0442\u0438\u0435 \u0443\u0434\u0432\u0430\u0438\u0432\u0430\u0435\u0442 \u0441\u0442\u0430\u0432\u043A\u0443 \u0438 \u043F\u0435\u0440\u0435\u0434\u0430\u0451\u0442 \u043F\u0440\u0438\u043D\u044F\u0432\u0448\u0435\u043C\u0443 \u043F\u0440\u0430\u0432\u043E \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0438\u0442\u044C \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0435 \u0443\u0434\u0432\u043E\u0435\u043D\u0438\u0435, \u043C\u0430\u043A\u0441\u0438\u043C\u0443\u043C \u0434\u043E 64. \u041E\u0431\u044B\u0447\u043D\u044B\u0435 \u043E\u0434\u043D\u043E, \u0434\u0432\u0430 \u0438\u043B\u0438 \u0442\u0440\u0438 \u043E\u0447\u043A\u0430 \u0437\u0430 \u043F\u043E\u0431\u0435\u0434\u0443 \u0443\u043C\u043D\u043E\u0436\u0430\u044E\u0442\u0441\u044F \u043D\u0430 \u0441\u0442\u0430\u0432\u043A\u0443. \u041A\u043E\u0433\u0434\u0430 \u043A\u043E\u043C\u0443-\u0442\u043E \u0432\u043F\u0435\u0440\u0432\u044B\u0435 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043E\u0434\u043D\u043E \u043E\u0447\u043A\u043E \u0434\u043E \u043F\u043E\u0431\u0435\u0434\u044B \u0432 \u043C\u0430\u0442\u0447\u0435, \u0442\u043E\u043B\u044C\u043A\u043E \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u043F\u0430\u0440\u0442\u0438\u0438 \u0443\u0434\u0432\u043E\u0435\u043D\u0438\u0435 \u043E\u0442\u043A\u043B\u044E\u0447\u0430\u0435\u0442\u0441\u044F: \u044D\u0442\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u043E \u041A\u0440\u043E\u0443\u0444\u043E\u0440\u0434\u0430."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0430",
              "Enter: \u0431\u0440\u043E\u0441\u0438\u0442\u044C \u043A\u0443\u0431\u0438\u043A\u0438, \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u043E \u0441\u0442\u0430\u0432\u043A\u0435 \u0438\u043B\u0438 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0448\u0430\u0448\u043A\u0443, \u0430 \u0437\u0430\u0442\u0435\u043C \u0435\u0451 \u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435.",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0430\u0442\u044C\u0441\u044F \u043F\u043E \u0434\u043E\u0441\u043A\u0435 \u0438\u043B\u0438 \u0432\u044B\u0431\u0438\u0440\u0430\u0442\u044C \u0440\u0435\u0448\u0435\u043D\u0438\u0435. \u0412\u0435\u0440\u0445\u043D\u0438\u0439 \u0440\u044F\u0434 \u0438\u0434\u0451\u0442 \u043E\u0442 24 \u0434\u043E 13, \u043D\u0438\u0436\u043D\u0438\u0439 \u2014 \u043E\u0442 1 \u0434\u043E 12, \u043E\u0431\u0430 \u0441\u043B\u0435\u0432\u0430 \u043D\u0430\u043F\u0440\u0430\u0432\u043E. \u0411\u0430\u0440 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u0441\u043B\u0435\u0432\u0430 \u043E\u0442 24, \u0441\u043D\u044F\u0442\u044B\u0435 \u0448\u0430\u0448\u043A\u0438 \u2014 \u0441\u043B\u0435\u0432\u0430 \u043E\u0442 1. \u0415\u0441\u043B\u0438 \u0435\u0441\u0442\u044C \u0448\u0430\u0448\u043A\u0430 \u043D\u0430 \u0431\u0430\u0440\u0435, \u043C\u043E\u0436\u043D\u043E \u0441\u0440\u0430\u0437\u0443 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043F\u0443\u043D\u043A\u0442 \u0432\u0432\u043E\u0434\u0430.",
              "Escape: \u043E\u0442\u043C\u0435\u043D\u0438\u0442\u044C \u0432\u044B\u0431\u043E\u0440 \u0448\u0430\u0448\u043A\u0438.",
              "V: \u043F\u0440\u043E\u0441\u043C\u0430\u0442\u0440\u0438\u0432\u0430\u0442\u044C \u0434\u043E\u0441\u043A\u0443, \u043D\u0435 \u043F\u0435\u0440\u0435\u0434\u0432\u0438\u0433\u0430\u044F \u0448\u0430\u0448\u043A\u0438.",
              "D: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u043A\u0443\u0431\u0438\u043A\u043E\u0432.",
              "\u041F\u0440\u043E\u0431\u0435\u043B: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u043A\u0443\u0431\u0438\u043A\u0438 \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0435\u043D\u0438\u044F.",
              "B: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0448\u0430\u0448\u043A\u0438 \u043E\u0431\u043E\u0438\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u043D\u0430 \u0431\u0430\u0440\u0435.",
              "Z: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u043D\u044F\u0442\u044B\u0435 \u0448\u0430\u0448\u043A\u0438 \u043E\u0431\u043E\u0438\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432.",
              "S: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0447\u0451\u0442 \u043C\u0430\u0442\u0447\u0430.")
          ]
